const CACHE='cricavo-shell-v20';const files=['./','./index.html','./styles.css','./app.js','./engine.js','./storage.js','./auth.js','./account.js','./cloud-backups.js','./auto-backup.js','./cloud-connection.js','./tournaments.js','./tournament-ui.js','./draw-ui.js','./awards.js','./fielding.js','./tournament-stats.js','./fixture-filters.js','./tournament-backups.js','./manifest.webmanifest','./icon.svg'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(files))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('cricavo-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==location.origin)return;if(url.pathname.endsWith('/config.json')||url.searchParams.has('code'))return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('./index.html')));return}e.respondWith(caches.match(e.request).then(cached=>cached||fetch(e.request)))});

